#!/usr/bin/env python3
"""
Autonomous Software Factory (factory.py)
Coordinates 7 sequential agents sharing context through filesystem artifacts
to architect, implement, review, test, document, and containerize a production-grade
LangGraph outbound lead pipeline.
"""

import os
