from pathlib import Path
from datetime import datetime

# ANSI Terminal Styling
class Style:
    HEADER = "\033[95m"
    BLUE = "\033[94m"
    CYAN = "\033[96m"
    GREEN = "\033[92m"
    YELLOW = "\033[93m"
    RED = "\033[91m"
    BOLD = "\033[1m"
    UNDERLINE = "\033[4m"
    RESET = "\033[0m"

def log_header(title: str):
    print(f"\n{Style.BOLD}{Style.CYAN}{'='*80}{Style.RESET}")
    print(f"{Style.BOLD}{Style.CYAN} [AUTONOMOUS FACTORY] {title.upper()}{Style.RESET}")
    print(f"{Style.BOLD}{Style.CYAN}{'='*80}{Style.RESET}")

def log_agent(name: str, action: str):
    timestamp = datetime.now().strftime("%H:%M:%S")
    print(f"{Style.BOLD}{Style.BLUE}[{timestamp}] 🤖 {name.upper()}:{Style.RESET} {action}")

def log_success(msg: str):
    print(f"  {Style.GREEN}✓ {msg}{Style.RESET}")

def log_warning(msg: str):
    print(f"  {Style.YELLOW}⚠ {msg}{Style.RESET}")

def log_error(msg: str):
    print(f"  {Style.RED}✗ {msg}{Style.RESET}")


class BaseAgent:
    def __init__(self, name: str, role: str, workspace: Path):
        self.name = name
        self.role = role
        self.workspace = workspace

    def run(self) -> bool:
        raise NotImplementedError


