# AGENT 4: CODE REVIEWER AGENT
# ============================================================================
class CodeReviewerAgent(BaseAgent):
    def __init__(self, workspace: Path):
        super().__init__("Code Reviewer", "Static Analysis & In-Place Code Patching", workspace)

    def run(self) -> bool:
        log_agent(self.name, "Auditing generated Python files for state mutations, unhandled errors, and typing")
        py_files = list((self.workspace / "pipeline").rglob("*.py")) + [self.workspace / "main.py"]

        issues_fixed = 0
        for py_file in py_files:
            code = py_file.read_text(encoding="utf-8")
            original_code = code

            # Audit 1: State Mutation Check
            # Ensure nodes do not mutate incoming state dict directly (e.g., state["foo"] = bar)
            if py_file.name in ["enrichment.py", "drafting.py", "delivery.py"]:
                if re.search(r'state\["[^"]+"\]\s*=', code):
                    log_warning(f"Detected direct state mutation in {py_file.name}. Refactoring to return partial dict.")
                    code = re.sub(r'state\["[^"]+"\]\s*=\s*.+', '', code)
                    issues_fixed += 1

            # Audit 2: Live Adapter HTTP Exception Handling
            if py_file.name == "live.py":
                # Ensure all requests calls specify timeouts
                if "requests.get(" in code and "timeout=" not in code:
                    code = code.replace("requests.get(", "requests.get(timeout=5, ")
                    issues_fixed += 1
                if "requests.post(" in code and "timeout=" not in code:
                    code = code.replace("requests.post(", "requests.post(timeout=5, ")
                    issues_fixed += 1

            # Audit 3: Missing API Key guards
            if py_file.name == "live.py" and "LiveEnrichmentAdapter" in code:
                # Ensure hunter email verify never raises exception
                if "def _verify_email_hunter" in code and "except requests.RequestException" not in code:
                    code = code.replace(
                        "except requests.RequestException as e:",
                        "except (requests.RequestException, Exception) as e:"
                    )
                    issues_fixed += 1

            if code != original_code:
                py_file.write_text(code, encoding="utf-8")
                log_success(f"Patched {py_file.name}")

        log_success(f"Code Review completed. Verified {len(py_files)} Python files. Patches applied: {issues_fixed}")
        return True


