# AGENT 7: DEVOPS ENGINEER AGENT
# ============================================================================
class DevOpsEngineerAgent(BaseAgent):
    def __init__(self, workspace: Path):
        super().__init__("DevOps Engineer", "Containerization & Orchestration", workspace)

    def run(self) -> bool:
        log_agent(self.name, "Creating Dockerfile, docker-compose.yml, and .dockerignore")

        # 1. Dockerfile
        dockerfile = self.workspace / "Dockerfile"
        dockerfile_content = """# Production Dockerfile for LangGraph Outbound Pipeline
FROM python:3.13-slim

ENV PYTHONDONTWRITEBYTECODE=1 \\
    PYTHONUNBUFFERED=1 \\
    DEBIAN_FRONTEND=noninteractive

WORKDIR /app

# Install system dependencies
RUN apt-get update && apt-get install -y --no-install-recommends \\
    curl \\
    && rm -rf /var/lib/apt/lists/*

# Install python dependencies
COPY requirements.txt .
RUN pip install --no-cache-dir -r requirements.txt

# Create non-root user
RUN useradd -m -u 1000 appuser && \\
    mkdir -p /app/staged_deliveries && \\
    chown -R appuser:appuser /app

# Copy application source
COPY --chown=appuser:appuser . .

USER appuser

VOLUME ["/app/staged_deliveries"]

ENTRYPOINT ["python", "main.py"]
CMD ["--domain", "cyber-corp.com"]
"""
        dockerfile.write_text(dockerfile_content, encoding="utf-8")
        log_success("Created Dockerfile")

        # 2. docker-compose.yml
        compose_file = self.workspace / "docker-compose.yml"
        compose_content = """services:
  outbound-pipeline:
    build:
      context: .
      dockerfile: Dockerfile
    container_name: langgraph-outbound-pipeline
    env_file:
      - .env.example
    environment:
      - DRY_RUN=true
      - APOLLO_MODE=stub
      - DRAFTING_MODE=stub
      - DELIVERY_MODE=stub
    volumes:
      - ./staged_deliveries:/app/staged_deliveries
    command: ["--domain", "cyber-corp.com"]
"""
        compose_file.write_text(compose_content, encoding="utf-8")
        log_success("Created docker-compose.yml")

        # 3. .dockerignore
        dockerignore = self.workspace / ".dockerignore"
        dockerignore_content = """.git
.gitignore
.venv/
__pycache__/
*.py[cod]
.pytest_cache/
.env
data/resume.json
staged_deliveries/
*.pdf
"""
        dockerignore.write_text(dockerignore_content, encoding="utf-8")
        log_success("Created .dockerignore")

        # 4. .env.example (Safe template for environment configuration)
        # CRITICAL SAFETY INVARIANT: The build process must NEVER generate,
        # regenerate, or overwrite .env directly. .env contains private API keys,
        # tokens, and manual configuration overrides that must only ever be edited
        # manually by the user. Only .env.example is safe to auto-sync.
        env_example = self.workspace / ".env.example"
        env_example_content = """GEMINI_API_KEY=
APOLLO_API_KEY=
INSTANTLY_API_KEY=
PHANTOMBUSTER_API_KEY=
HUNTER_API_KEY=
LEMLIST_API_KEY=
DRY_RUN=true
DISCOVERY_MODE=stub
APOLLO_MODE=stub
DRAFTING_MODE=stub
DELIVERY_MODE=stub
COMPANY_SIZE=any
MAX_SENDS_PER_DAY=10
MAX_SENDS_PER_WEEK=50
ENRICHMENT_DELAY_MS=0
DELIVERY_DELAY_MS=0
"""
        env_example.write_text(env_example_content, encoding="utf-8")
        log_success("Created .env.example (template safe for auto-sync; .env is protected and never touched)")
        return True


# ============================================================================
# FACTORY ORCHESTRATOR
# ============================================================================
class AutonomousSoftwareFactory:
    def __init__(self, workspace_path: str = "."):
        self.workspace = Path(workspace_path).resolve()
        self.agents = [
            ProductManagerAgent(self.workspace),
            SystemsArchitectAgent(self.workspace),
            SeniorDeveloperAgent(self.workspace),
            CodeReviewerAgent(self.workspace),
            QATesterAgent(self.workspace),
            TechnicalWriterAgent(self.workspace),
            DevOpsEngineerAgent(self.workspace),
        ]

    def build(self) -> bool:
        log_header("Initializing 7-Agent Sequential Assembly Line")
        start_time = datetime.now()

        # CRITICAL INVARIANT: .env must NEVER be modified by any agent in the factory build.
        env_path = self.workspace / ".env"
        env_bytes_before = env_path.read_bytes() if env_path.exists() else None

        for idx, agent in enumerate(self.agents, 1):
            print(f"\n{Style.BOLD}{Style.YELLOW}─── [STEP {idx}/7] {agent.name.upper()} ({agent.role}) ───{Style.RESET}")
            success = agent.run()
            if not success:
                log_error(f"Agent {agent.name} encountered a critical error. Halting factory build.")
                return False

        if env_path.exists() and env_bytes_before is not None:
            if env_path.read_bytes() != env_bytes_before:
                log_error("CRITICAL SAFETY VIOLATION: .env was modified by the agent build process!")
                raise RuntimeError(".env was modified during factory build — .env must never be touched by agents!")

        duration = (datetime.now() - start_time).total_seconds()
        log_header(f"Factory Build Succeeded in {duration:.2f}s")
        print(f"{Style.BOLD}{Style.GREEN}All 7 agents successfully executed and verified the codebase!{Style.RESET}\n")
        return True


if __name__ == "__main__":
    factory = AutonomousSoftwareFactory()
    success = factory.build()
    sys.exit(0 if success else 1)
